import test from 'node:test';import assert from 'node:assert/strict';
import {ITEMS,SPECIES,applySupply} from '../repertoire.js?v=5.6.0';import {Battle,makeEnemy,encounterEnemies} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';
function battle(){const heroes=[defaultHero(0,10),defaultHero(1,10),defaultHero(2,10)],enemies=encounterEnemies(5,false,2);heroes.forEach((h,i)=>{h.x=i;h.y=0;});enemies.forEach(e=>{e.x=0;e.y=0;});const b=new Battle({heroes,enemies});heroes[0].atb=1;return b;}
test('every new consumable is stocked by the campaign, uniquely identified and backed by a useful description',()=>{assert.equal(ITEMS.length,45);assert.equal(new Set(ITEMS.map(i=>i.id)).size,45);for(const i of ITEMS.slice(27)){assert.ok(i.chapter<=24);assert.ok(i.price>0);assert.ok(i.description.length>20);}assert.equal(SPECIES.filter(s=>s.atlas==='bestiary2').length,12);});
test('rally gives readiness to other living allies without refunding its own turn',()=>{const b=battle(),[a,h]=b.heroes,old=h.atb,inv={rallyWhistle:1};assert.ok(applySupply(b,inv,'rallyWhistle',a,b.enemies[0]));assert.equal(a.atb,0);assert.equal(h.atb,old+.35);assert.equal(inv.rallyWhistle,0);});
test('group cleansing and dispelling affect the intended side and ineffective use costs nothing',()=>{const b=battle(),a=b.heroes[0],inv={rainSalt:2,nullBell:2};b.heroes[1].status.burn=5;b.enemies[0].status.guard=6;assert.ok(applySupply(b,inv,'rainSalt',a,b.enemies[0]));assert.equal(b.heroes[1].status.burn,undefined);assert.equal(b.enemies[0].status.guard,6);a.atb=1;assert.equal(applySupply(b,inv,'rainSalt',a,b.enemies[0]),false);assert.equal(inv.rainSalt,1);assert.equal(a.atb,1);assert.ok(applySupply(b,inv,'nullBell',a,b.enemies[0]));assert.equal(b.enemies[0].status.guard,undefined);});
test('delay retains telegraph proportions and breaker cancels all charged attacks once',()=>{const b=battle(),a=b.heroes[0],inv={clockSand:1,breakerChime:1};for(const e of b.enemies){e.intent={left:.6,total:1.2};e.atb=.8;}assert.ok(applySupply(b,inv,'clockSand',a,b.enemies[0]));assert.equal(b.enemies[0].intent.left,1.6);assert.equal(b.enemies[0].intent.total,2.2);a.atb=1;assert.ok(applySupply(b,inv,'breakerChime',a,b.enemies[0]));assert.ok(b.enemies.every(e=>!e.intent&&e.atb===0&&e.status.stagger>0));});
test('new AI traits execute and survive battle save replay',()=>{for(const trait of ['chorus','molt','forge','siphon','erase','tempo','pressure']){const b=battle(),e=b.enemies[0];e.trait=trait;e.turn=2;e.hp=e.maxHp*.4;e.status.burn=5;b.heroes[0].status.shield=90;const before=b.heroes[0].mp;b.planEnemy(e);const intent={...e.intent,shape:'burst',x:0,y:0};b.executeIntent(e,intent);if(trait==='chorus')assert.ok(e.status.haste);if(trait==='molt')assert.ok(e.molted);if(trait==='siphon')assert.ok(b.heroes[0].mp<before);if(trait==='erase')assert.ok(b.heroes[0].status.shield<=50);if(trait==='tempo')assert.ok(e.status.haste);const saved=b.snapshot(),copy=battle();copy.restore(saved);assert.equal(copy.enemies[0].trait,trait);}});
